declare(strict_types=1);require_once __DIR__.'/_helper.php';home_visit_require_access();if(!home_visit_can_manage()){http_response_code(403);exit('Akses Home Visit ditolak.');}$tapel=home_visit_active_tapel($pdo);if(!$tapel)exit('Belum ada Tahun Pelajaran aktif.');
$errors=[];$siswa=[];$guru=$pdo->query("SELECT id,nama FROM guru WHERE status='aktif' ORDER BY nama")->fetchAll();$stStudents=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,mk.nama AS kelas FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=? AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE s.status='aktif' ORDER BY mk.urutan,mk.nama,s.nama");$stStudents->execute([(int)$tapel['id']]);$students=$stStudents->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$sid=(int)($_POST['siswa_id']??0);$tr=$_POST['tanggal_rencana']?:null;$tp=$_POST['tanggal_pelaksanaan']?:null;$w=$_POST['waktu']?:null;$al=trim((string)($_POST['alasan']??''));$tu=trim((string)($_POST['tujuan']??''));$hasil=trim((string)($_POST['hasil']??''));$cat=trim((string)($_POST['catatan']??''));$tl=trim((string)($_POST['tindak_lanjut']??''));$status=(string)($_POST['status']??'direncanakan');$pid=(int)($_POST['petugas_id']??0)?:null;if(!$sid)$errors[]='Siswa wajib dipilih.';if($al==='')$errors[]='Alasan wajib diisi.';if(!in_array($status,['direncanakan','dilaksanakan','ditunda','dibatalkan'],true))$status='direncanakan';if(!$errors){$st=$pdo->prepare("INSERT INTO home_visit (siswa_id,tahun_pelajaran_id,tanggal_rencana,tanggal_pelaksanaan,waktu,alasan,tujuan,hasil,catatan,tindak_lanjut,status,petugas_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())");$st->execute([$sid,(int)$tapel['id'],$tr,$tp,$w,$al,$tu,$hasil,$cat,$tl,$status,$pid]);$id=(int)$pdo->lastInsertId();home_visit_audit($pdo,'CREATE',$id,'Mencatat Home Visit');header('Location: '.BASE_URL.'home_visit/detail.php?id='.$id);exit;}}
$page_title='Catat Home Visit';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main"><header class="topbar"><div class="topbar-title">Catat Home Visit</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content home-visit-module"><div class="card" style="max-width:1000px;margin:auto"><div class="section-title"><div><h2><i class="bi bi-house-door-fill"></i> Catat Home Visit</h2><p>Tahun Pelajaran <?=e($tapel['nama'])?></p></div><a class="btn btn-secondary" href="<?=BASE_URL?>home_visit/index.php">Kembali</a></div><?php foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?><form method="post"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Siswa *</label><div class="student-picker" data-student-picker data-items="<?=e(json_encode(array_map(fn($r)=>['id'=>(int)$r['id'],'nis'=>(string)$r['nis'],'nisn'=>(string)($r['nisn']??''),'nama'=>(string)$r['nama'],'kelas'=>(string)($r['kelas']??'')],$students),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>"><input type="hidden" name="siswa_id" data-student-value value="<?=e((string)((int)($_POST['siswa_id']??0)))?>"><div class="student-picker-toolbar"><select class="form-control" data-student-class><option value="">Pilih Kelas Terlebih Dahulu</option></select><input class="form-control" type="search" data-student-search placeholder="Pilih kelas terlebih dahulu, lalu cari nama/NIS/NISN..." autocomplete="off"></div><div data-student-selected></div><div class="student-picker-results" data-student-results></div><div class="student-picker-empty" data-student-empty hidden>Tidak ada siswa yang sesuai.</div><small class="student-picker-help"><i class="bi bi-funnel"></i> Pilih kelas terlebih dahulu, kemudian pilih siswa.</small></div></div><div class="col-md-3"><label class="form-label">Tanggal Rencana</label><input type="date" name="tanggal_rencana" class="form-control" value="<?=e($_POST['tanggal_rencana']??date('Y-m-d'))?>"></div><div class="col-md-3"><label class="form-label">Tanggal Pelaksanaan</label><input type="date" name="tanggal_pelaksanaan" class="form-control" value="<?=e($_POST['tanggal_pelaksanaan']??'')?>"></div><div class="col-md-3"><label class="form-label">Waktu</label><input type="time" name="waktu" class="form-control" value="<?=e($_POST['waktu']??'')?>"></div><div class="col-md-5"><label class="form-label">Petugas</label><select name="petugas_id" class="form-control"><option value="">Belum ditentukan</option><?php foreach($guru as $g):?><option value="<?=$g['id']?>" <?=((int)($_POST['petugas_id']??0)==$g['id'])?'selected':''?>><?=e($g['nama'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Status</label><select name="status" class="form-control"><?php foreach(['direncanakan','dilaksanakan','ditunda','dibatalkan'] as $v):?><option value="<?=$v?>" <?=($_POST['status']??'direncanakan')===$v?'selected':''?>><?=e(home_visit_status_label($v))?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Alasan / Permasalahan *</label><textarea name="alasan" class="form-control" rows="3" required><?=e($_POST['alasan']??'')?></textarea></div><div class="col-12"><label class="form-label">Tujuan Kunjungan</label><textarea name="tujuan" class="form-control" rows="2"><?=e($_POST['tujuan']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Hasil Kunjungan</label><textarea name="hasil" class="form-control" rows="4"><?=e($_POST['hasil']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Catatan</label><textarea name="catatan" class="form-control" rows="4"><?=e($_POST['catatan']??'')?></textarea></div><div class="col-12"><label class="form-label">Tindak Lanjut</label><textarea name="tindak_lanjut" class="form-control" rows="3"><?=e($_POST['tindak_lanjut']??'')?></textarea></div></div><div style="margin-top:18px;display:flex;justify-content:flex-end;gap:10px"><a class="btn btn-secondary" href="<?=BASE_URL?>home_visit/index.php">Batal</a><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan</button></div></form></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
